#include <bits/stdc++.h>
using namespace std;

string canon(const string &s) {
    size_t p = s.find_first_not_of('0');
    return p == string::npos ? "0" : s.substr(p);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    unordered_map<string, long long> counts;
    string s;
    for (int i = 0; i < n; i++) { cin >> s; counts[canon(s)]++; }
    cin >> s;
    string target = canon(s);
    long long answer = 0;
    for (size_t i = 1; i < target.size(); i++) {
        string a = target.substr(0, i), b = target.substr(i);
        auto ia = counts.find(a), ib = counts.find(b);
        if (ia == counts.end() || ib == counts.end()) continue;
        // the same value cannot reuse the same index
        answer += ia->second * (ib->second - (a == b ? 1 : 0));
    }
    cout << answer << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static String canon(String s) {
        int p = 0;
        while (p < s.length() - 1 && s.charAt(p) == '0') p++;
        return s.substring(p);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        HashMap<String, Long> counts = new HashMap<>();
        for (int i = 0; i < n; i++) counts.merge(canon(st.nextToken()), 1L, Long::sum);
        String target = canon(st.nextToken());
        long answer = 0;
        for (int i = 1; i < target.length(); i++) {
            String a = target.substring(0, i), b = target.substring(i);
            long left = counts.getOrDefault(a, 0L), right = counts.getOrDefault(b, 0L);
            // the same value cannot reuse the same index
            if (left > 0 && right > 0) answer += left * (right - (a.equals(b) ? 1 : 0));
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func canon(s string) string {
	t := strings.TrimLeft(s, "0")
	if t == "" {
		return "0"
	}
	return t
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	counts := make(map[string]int, n)
	for i := 0; i < n; i++ {
		var s string
		fmt.Fscan(in, &s)
		counts[canon(s)]++
	}
	var s string
	fmt.Fscan(in, &s)
	target := canon(s)
	answer := 0
	for i := 1; i < len(target); i++ {
		a, b := target[:i], target[i:]
		right := counts[b]
		if a == b {
			right-- // the same value cannot reuse the same index
		}
		if counts[a] > 0 && right > 0 {
			answer += counts[a] * right
		}
	}
	fmt.Println(answer)
}
